def countValidWords(sentence: str) -> int:
    def is_valid(token: str) -> bool:
        if not token:
            return False

        hyphen_used = False
        n = len(token)
        for i, c in enumerate(token):
            if c.isdigit():
                return False
            if c in "!.,":  # punctuation
                if i != n - 1:
                    return False  # must be at end
            if c == '-':
                if hyphen_used:
                    return False  # at most one hyphen
                if i == 0 or i == n - 1:
                    return False  # cannot be at start or end
                if not (token[i - 1].islower() and token[i + 1].islower()):
                    return False  # must be surrounded by lowercase
                hyphen_used = True
        return True

    tokens = sentence.strip().split()
    count = 0
    for token in tokens:
        if is_valid(token):
            count += 1
    return count
